import json
import os
import re

def task_func(file_path, attribute, INPUT_JSON, EMAIL_REGEX):
    # Check if file exists
    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    try:
        # Load JSON data from file
        with open(file_path, 'r') as f:
            data = json.load(f)

        # Validate data against schema
        for key, value in INPUT_JSON['properties'].items():
            if key not in data:
                raise ValueError(f"Required attribute '{key}' is missing")
            elif not isinstance(data[key], value['type']):
                raise ValueError(f"Type mismatch for attribute '{key}'. Expected {value['type'].__name__}, got {type(data[key]).__name__}")
            elif key == 'email' and not re.match(EMAIL_REGEX, data[key]):
                raise ValueError(f"Invalid email format for attribute '{key}'")

        return data.get(attribute)

    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format in file")
```

